<script setup>
import { computed, inject, ref } from 'vue'
import AppIcon from '../components/AppIcon.vue'
import MetricCard from '../components/MetricCard.vue'
import LineChart from '../components/LineChart.vue'
import BarComparison from '../components/BarComparison.vue'
import { uiContextKey } from '../ui/context.js'
import { appOptions, chartDates, getMockModels } from '../ui/mock-data.js'
const { previewAppId } = inject(uiContextKey,{previewAppId:ref('10350')})
const startDate=ref('2026-10-01'),endDate=ref('2026-10-13'),granularity=ref('DAILY'),notice=ref('')
const enabled = ref(['Last Day','Rolling Mean','Exponential Decay'])
const models=computed(()=>getMockModels(previewAppId.value))
const ranking=computed(()=>[...models.value].sort((a,b)=>Number(b.ndcg)-Number(a.ndcg)))
const best=computed(()=>ranking.value[0])
const visibleModels=computed(()=>models.value.filter(model=>enabled.value.includes(model.name)))
const trend=computed(()=>visibleModels.value.map(model=>({name:model.name,color:model.color,values:model.trend})))
</script>
<template>
  <div data-page="backtest"><header class="page-heading"><div><h1>模型回测与比较</h1><p>严格时间滚动回测，按 AppID 分别评价，在相同历史窗口下比较候选方案。</p></div><span class="source-badge">UI MOCK · 非真实评估</span></header>
    <section class="card filter-card"><div class="filter-field"><label for="backtest-app">AppID</label><select id="backtest-app" v-model="previewAppId"><option v-for="option in appOptions" :key="option.id" :value="option.id">{{ option.label }}</option></select></div><div class="filter-field"><label for="backtest-start">回测日期</label><div class="date-range"><input id="backtest-start" v-model="startDate" type="date" aria-label="回测开始日期"><span class="date-separator">—</span><input v-model="endDate" type="date" aria-label="回测结束日期"></div></div><div class="segmented"><button :class="{active:granularity==='DAILY'}" @click="granularity='DAILY'">日粒度</button><button :class="{active:granularity==='WEEKLY'}" @click="granularity='WEEKLY'">周粒度</button></div><button class="btn btn-primary filter-spacer" @click="notice='当前仅预览回测配置，未提交回测任务。图表与指标为独立 UI Mock，不能用于正式选模。'"><AppIcon name="play" :size="14"/>开始回测</button></section>
    <div v-if="notice" class="notice notice--amber" role="status"><AppIcon name="info" :size="16"/>{{ notice }}</div>
    <div class="context-note"><span>App {{ previewAppId }} · {{ granularity==='DAILY' ? '日' : '周' }}粒度配置 · {{ startDate }} — {{ endDate }}</span><span>以下固定样例未因配置变化重新计算</span></div>
    <section class="metric-grid"><MetricCard label="Recall@50" :value="best.recall" icon="file" note="UI 样例最佳方案 · 非评估成绩"/><MetricCard label="NDCG@50" :value="best.ndcg" icon="chart" note="排序质量 · 静态样例"/><MetricCard label="Top50 流量覆盖率" :value="best.coverage" icon="pie" tone="green" note="固定评价口径的 UI 示例"/><MetricCard label="MAPE" value="—" icon="backtest" note="完整有效标签未接入，不展示数值"/></section>
    <div class="chart-grid chart-grid--equal"><section class="card"><header class="card-heading"><h2>各模型在不同历史窗口的 Recall@50</h2><small>UI Mock</small></header><LineChart :labels="chartDates" :series="trend" unit="%" :max-y="100" aria-label="UI Mock 各模型历史窗口Recall@50趋势"/><div class="chart-foot">固定时间窗口的静态样例，不代表已运行滚动回测。</div></section><section class="card"><header class="card-heading"><h2>模型综合指标对比</h2><small>统一样例窗口</small></header><BarComparison :models="visibleModels"/><div class="chart-foot">为便于共轴展示，NDCG@50 在图中乘以 100；原值见下方表格。</div></section></div>
    <section class="card table-card"><header class="card-heading"><h2>模型比较与排名</h2><span class="source-badge source-badge--muted">同 App · 同粒度 · 同样例窗口</span></header><div class="model-choices"><label v-for="model in models" :key="model.name"><input v-model="enabled" type="checkbox" :value="model.name"><i :style="{background:model.color}"/>{{ model.name }}</label><span>勾选控制图表展示</span></div><div class="table-scroll"><table><thead><tr><th>样例排名</th><th>模型 / 方法</th><th>Recall@50</th><th>NDCG@50</th><th>Top50 流量覆盖率</th><th>MAPE</th><th>选型说明</th></tr></thead><tbody><tr v-for="(model,index) in ranking" :key="model.name" :class="{'best-row':index===0}"><td><span class="ranking-number" :class="{'ranking-number--best':index===0}">{{ index+1 }}</span></td><td><strong class="model-name">{{ model.name }}</strong><span class="file-subtitle">{{ model.description }}</span></td><td>{{ model.recall }}</td><td>{{ model.ndcg }}</td><td>{{ model.coverage }}</td><td class="text-muted">不适用 / 未提供</td><td><span v-if="index===0" class="status-pill status-pill--processing">UI 样例最佳</span><span v-else class="text-muted">仅展示对比</span></td></tr></tbody></table></div><div class="backtest-conclusion"><span class="conclusion-icon"><AppIcon name="backtest" :size="22"/></span><div><strong>样例中 {{ best.name }} 的 NDCG@50 最高</strong><p>该标识仅依据本页 UI Mock 数值。正式选型需完整时间滚动回测与可比标签证据，本页不会切换模型。</p></div><span class="source-badge source-badge--muted">正式选模未接入</span></div></section>
    <div class="backtest-rules"><span><AppIcon name="check" :size="13"/>特征截止日早于目标窗口</span><span><AppIcon name="check" :size="13"/>不同 AppID 独立评估</span><span><AppIcon name="check" :size="13"/>缺失标签不补零</span><span><AppIcon name="info" :size="13"/>LightGBM 未列为已部署能力</span></div>
  </div>
</template>
<style scoped>.model-choices{display:flex;align-items:center;gap:20px;padding:0 20px 17px;flex-wrap:wrap}.model-choices label{display:flex;align-items:center;gap:6px;color:#6b829f;font-size:11px;cursor:pointer}.model-choices input{accent-color:#1677ff;width:12px;height:12px;margin:0}.model-choices i{width:6px;height:6px;border-radius:50%}.model-choices>span{margin-left:auto;font-size:9px;color:#a3afbe}.best-row{background:#f1f7ff}.best-row td{color:#347ad0}.model-name{font-weight:550;font-size:12px}.ranking-number{display:grid;place-items:center;width:22px;height:22px;color:#8398b4;background:#f3f6fb;border-radius:4px;font-size:10px}.ranking-number--best{color:#1677ff;background:#deecff}.backtest-conclusion{display:flex;align-items:center;gap:15px;padding:18px 20px;background:#f8fbff;border-top:1px solid #edf2fa;border-radius:0 0 7px 7px}.conclusion-icon{display:grid;place-items:center;background:#edf5ff;color:#1677ff;border-radius:6px;width:40px;height:40px;flex:none}.backtest-conclusion strong{font-size:12px;color:#4a6a93;font-weight:550}.backtest-conclusion p{margin:7px 0 0;font-size:10px;color:#9aa8ba;line-height:1.8}.backtest-conclusion>.source-badge{margin-left:auto}.backtest-rules{display:flex;align-items:center;gap:23px;flex-wrap:wrap;font-size:10px;color:#96a5b9;margin-top:19px}.backtest-rules span{display:flex;align-items:center;gap:6px}@media(max-width:760px){.backtest-conclusion{flex-wrap:wrap}.backtest-conclusion>.source-badge{margin-left:55px}.context-note{flex-wrap:wrap}}</style>
